// Suppression-set acceptance tests (eviction task 2.1, D3): a policy
// eviction of a document-named build marks the item in the process-lifetime
// set; the frontier stops fronting the suppressed position (no job, no pin,
// no bytes); the integrity sweep skips the suppressed repack with ONE INFO
// line (the gate-refusal pattern); and a real play — POST /play through the
// Deps.Play closure — re-arms the item before the pack decisions run.

// supFfOpen is the gate-open ffprobe fixture (the same shape the gate tests
// judge): h264/aac MKV — packable with the opt-in knob off, so the gate can
// never be the refusal under test; only the suppression may stop a pack.
const supFfOpen = `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`

// supSeed opens a fresh store with one streams-enabled tv library (the
// column default), seeds its one directory-backed series, and seeds one live
// episode item per docs key (id → document) under that series. It returns
// the store, its context, and an empty artifact root.
func supSeed(t *testing.T, docs map[string]map[string]any) (*store.Store, context.Context, string) {
	t.Helper()
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "suppression.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	libID, err := st.CreateLibrary(ctx, "tv", "/media/suppression", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	if err := st.PutSeries(ctx, store.Series{
		ModuleID: "tv", LibraryID: libID, RelativePath: "Show", SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutSeries: %v", err)
	}
	for id, doc := range docs {
		raw, err := json.Marshal(doc)
		if err != nil {
			t.Fatalf("marshal doc %s: %v", id, err)
		}
		if err := st.PutItem(ctx, store.Item{
			ID: id, ModuleID: "tv", LibraryID: libID, FileID: id,
			RelativePath: "Show/" + id + ".mkv", MediaType: "tv",
			Document: raw, SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
	}
	return st, ctx, filepath.Join(t.TempDir(), "streams")
}

// supBuild lays down one build directory holding one segment of exactly
// size bytes (real bytes — the budget case reads them as disk truth).
func supBuild(t *testing.T, root, itemID, name string, size int64) string {
	t.Helper()
	p := filepath.Join(root, itemID, name)
	if err := os.MkdirAll(p, 0o755); err != nil {
		t.Fatalf("mkdir %s: %v", p, err)
	}
	if err := os.WriteFile(filepath.Join(p, "seg0.ts"), make([]byte, size), 0o644); err != nil {
		t.Fatalf("write segment in %s: %v", p, err)
	}
	return p
}

// supDoc builds an episode document whose streams namespace carries the
// given packaging state and (optional) build nonce beside the gate-open
// ffprobe facts.
func supDoc(state, nonce string) map[string]any {
	var facts map[string]any
	if err := json.Unmarshal([]byte(supFfOpen), &facts); err != nil {
		panic("bad ffprobe fixture: " + err.Error())
	}
	streams := map[string]any{"state": state}
	if nonce != "" {
		streams["nonce"] = nonce
	}
	return map[string]any{"ffprobe": facts, "streams": streams}
}

// supState reads one item's streams state back off the store.
func supState(t *testing.T, ctx context.Context, st *store.Store, id string) string {
	t.Helper()
	row, err := st.GetItem(ctx, id, access.System())
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	streams, _ := decodeItemDoc(row.Document)["streams"].(map[string]any)
	state, _ := streams["state"].(string)
	return state
}

// supRecorder returns an enqueue seam that records every observed enqueue
// (a stub lane: no pack ever runs, so any effect must come from the code
// under test).
func supRecorder() (func(string) error, *[]string) {
	seen := &[]string{}
	return func(id string) error { *seen = append(*seen, id); return nil }, seen
}

// TestEvictionSuppressesRefront is the churn-killer's core pin (eviction
// task 2.1): a budget eviction of a DOCUMENT-NAMED build marks the item in
// the suppression set, the following frontier sweeps enqueue nothing for the
// suppressed position (and pin nothing, and count no bytes for it), and the
// integrity sweep stays silent too. The control sweep fronts the very same
// fixture when the set is absent — only the suppression explains the
// silence, so the test can fail on a lost mark, a lost consult, or a lost
// threading.
func TestEvictionSuppressesRefront(t *testing.T) {
	st, ctx, root := supSeed(t, map[string]map[string]any{
		"itm_front": supDoc("complete", "n1"),
	})
	build := supBuild(t, root, "itm_front", "n1", 512)
	sup := newSuppressionSet()

	// The policy eviction: a budget that cannot be met without taking the
	// document-named build itself (the only directory on disk).
	sweepBudget(ctx, st, root, dirSize(build)-1, nil, sup)
	if _, err := os.Stat(build); !os.IsNotExist(err) {
		t.Fatalf("document-named build survived the budget eviction (stat err %v)", err)
	}
	if state := supState(t, ctx, st, "itm_front"); state != stream.StateNone {
		t.Fatalf("streams state = %q, want none after the unpublish", state)
	}
	if !sup.contains("itm_front") {
		t.Fatal("the evicted item was never marked — the budget sweep's mark rule is dead")
	}

	// The control: with NO suppression set, the same fixture fronts — the
	// pilot job for the one episode, enqueued through the seam and pinned.
	enqueueCtl, ctl := supRecorder()
	frontedCtl, _ := sweepFrontier(ctx, st, root, enqueueCtl, 1024, false, nil)
	if len(*ctl) != 1 || (*ctl)[0] != "itm_front" {
		t.Fatalf("control enqueued = %v, want exactly itm_front — the fixture must front un-suppressed", *ctl)
	}
	if !frontedCtl["itm_front"] {
		t.Fatalf("control fronted = %v, want itm_front pinned", frontedCtl)
	}

	// Suppressed: the same sweep sees no job, no pin, no bytes.
	enqueueSup, supEnq := supRecorder()
	frontedSup, _ := sweepFrontier(ctx, st, root, enqueueSup, 1024, false, sup)
	if len(*supEnq) != 0 {
		t.Fatalf("suppressed enqueued = %v, want nothing — a suppressed position emits no job", *supEnq)
	}
	if frontedSup["itm_front"] {
		t.Fatalf("suppressed fronted = %v, want empty — no pin, no bytes", frontedSup)
	}

	// The integrity sweep honors the mark too: nothing enters the lane.
	validate := func(itemID, nonce string) error { return errors.New("segment missing") }
	enqueueInt, intEnq := supRecorder()
	sweepIntegrity(ctx, st, root, validate, enqueueInt, false, sup)
	if len(*intEnq) != 0 {
		t.Fatalf("suppressed integrity enqueued = %v, want nothing — the suppressed repack skips", *intEnq)
	}
}

// TestIntegrityHonorsSuppression pins the integrity-side consult (eviction
// D3): a complete-state pointer at a GONE directory — the aftermath of a
// failed unpublish, best-effort by contract — would repack straight into the
// churn the suppression exists to kill; the mark stops it with ONE INFO line
// (the gate-refusal pattern), no enqueue, and no ledger row. The control
// fixture — the very same broken pointer with no mark — repacks, so only the
// suppression explains the silence.
func TestIntegrityHonorsSuppression(t *testing.T) {
	// brokenSeed lays down the gone-directory pointer: state complete naming
	// n1, no directory on disk (the failed unpublish's residue), and an
	// always-broken validator with a gate-open codec shape (the gate can
	// never be the refusal under test).
	brokenSeed := func(t *testing.T) (*store.Store, context.Context, string) {
		st, ctx, root := supSeed(t, map[string]map[string]any{
			"itm_gone": supDoc("complete", "n1"),
		})
		// The item's artifact directory survives the eviction; only the
		// named build under it is gone (evictDir's aftermath).
		if err := os.MkdirAll(filepath.Join(root, "itm_gone"), 0o755); err != nil {
			t.Fatalf("mkdir item dir: %v", err)
		}
		return st, ctx, root
	}
	validate := func(itemID, nonce string) error { return errors.New("segment missing") }

	t.Run("suppressed pointer stays unrep", func(t *testing.T) {
		st, ctx, root := brokenSeed(t)
		sup := newSuppressionSet()
		sup.mark("itm_gone")

		var buf bytes.Buffer
		prev := slog.Default()
		slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
		t.Cleanup(func() { slog.SetDefault(prev) })

		enqueue, seen := supRecorder()
		sweepIntegrity(ctx, st, root, validate, enqueue, false, sup)

		if len(*seen) != 0 {
			t.Fatalf("enqueued = %v, want nothing — the suppressed repack never enters the lane", *seen)
		}
		// Exactly ONE INFO line, naming the item and the suppression.
		lines := strings.Split(strings.TrimSpace(buf.String()), "\n")
		marks := 0
		for _, line := range lines {
			if strings.Contains(line, "repack suppressed by eviction") {
				marks++
				if !strings.Contains(line, "itm_gone") {
					t.Errorf("suppression line = %q, want the item", line)
				}
			}
			if strings.Contains(line, "fronted repack") {
				t.Errorf("suppressed item fronted anyway: %q", line)
			}
		}
		if marks != 1 {
			t.Errorf("suppression lines = %d, want exactly 1 (buf = %s)", marks, buf.String())
		}
		// Hard negative: the skip is a policy verdict, never a pack failure —
		// no pack_failed ledger row may exist.
		failures, err := st.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(failures) != 0 {
			t.Errorf("ledger rows = %d, want 0 — the suppression must never write one", len(failures))
		}
	})

	t.Run("unmarked control repacks", func(t *testing.T) {
		// The very same broken pointer with NO mark: the judge repacks —
		// exactly the churn the suppression exists to kill.
		st, ctx, root := brokenSeed(t)
		enqueue, seen := supRecorder()
		sweepIntegrity(ctx, st, root, validate, enqueue, false, nil)
		if len(*seen) != 1 || (*seen)[0] != "itm_gone" {
			t.Fatalf("enqueued = %v, want exactly itm_gone — the unmarked repack is the churn baseline", *seen)
		}
	})
}

// TestPlayClearsSuppression pins the re-arm (eviction D3): the suppression
// holds the frontier (nothing fronts the marked item), a real play — POST
// /play through the wired Deps.Play closure — clears the mark BEFORE it
// delegates to the pack decisions (pack-on-play enqueues), and the next
// sweep fronts the re-armed item again.
func TestPlayClearsSuppression(t *testing.T) {
	st, ctx, root := supSeed(t, map[string]map[string]any{
		"itm_play": supDoc("none", ""),
	})
	sup := newSuppressionSet()
	sup.mark("itm_play")
	enqueue, seen := supRecorder()

	// The mark holds the frontier: nothing fronts the suppressed item.
	_, _ = sweepFrontier(ctx, st, root, enqueue, 1024, false, sup)
	if len(*seen) != 0 {
		t.Fatalf("pre-play enqueued = %v, want nothing — the suppression holds", *seen)
	}

	// POST /play through the wired Deps.Play closure over real HTTP.
	h := api.New(api.Deps{
		AdminToken: "sup-play-token",
		Store:      st,
		Play:       newPlayClosure(st, enqueue, false, sup),
	})
	srv := httptest.NewServer(h)
	t.Cleanup(srv.Close)

	req, err := http.NewRequest(http.MethodPost, srv.URL+"/api/v1/items/itm_play/play", strings.NewReader(`{"retry":false}`))
	if err != nil {
		t.Fatalf("new request: %v", err)
	}
	req.Header.Set("Authorization", "Bearer sup-play-token")
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("POST /play: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusAccepted {
		t.Fatalf("POST /play status = %d, want 202 — pack-on-play answers the pack", resp.StatusCode)
	}
	var body struct {
		Queued bool `json:"queued"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		t.Fatalf("decode play response: %v", err)
	}
	if !body.Queued {
		t.Fatal("body.queued = false, want true — the re-armed play enqueues the pack")
	}
	if len(*seen) != 1 || (*seen)[0] != "itm_play" {
		t.Fatalf("enqueued = %v, want exactly itm_play, once — the pack enqueued through the closure", *seen)
	}
	if sup.contains("itm_play") {
		t.Fatal("the mark survived the play — the re-arm never cleared the suppression")
	}

	// Re-armed: the next sweep fronts the item again.
	enqueue2, seen2 := supRecorder()
	fronted, _ := sweepFrontier(ctx, st, root, enqueue2, 1024, false, sup)
	if len(*seen2) != 1 || (*seen2)[0] != "itm_play" {
		t.Fatalf("post-play enqueued = %v, want exactly itm_play — the re-arm re-fronts", *seen2)
	}
	if !fronted["itm_play"] {
		t.Fatalf("post-play fronted = %v, want itm_play pinned again", fronted)
	}
}
